//! 2x polyphase oversampler for bridging sub-96 kHz hosts to the 96 kHz model.
//!
//! The GRU is trained at 96 kHz. When the host runs below 96 kHz the plugin
//! upsamples 2x, runs the model on each oversampled sample, then downsamples.
//!
//! Both directions use a single 63-tap windowed-sinc (Kaiser, beta = 8.6)
//! half-band low-pass FIR, generated by `tools/gen_fir_coeffs.py`. The FIR is
//! scaled x2 so that, applied to a zero-stuffed stream, its DC gain is unity
//! (a constant input yields a constant 2x output -> both interpolated phases
//! converge to the input value, satisfying `upsample_dc_returns_constant`).
//!
//! The 63-tap length meets the >= 80 dB stopband spec much closer to Nyquist
//! than the previous 31-tap design: rejection reaches ~80 dB by ~0.28 of the
//! 2x rate (the unscaled firwin response first crosses -80 dB at ~0.294
//! cycles/sample, vs ~0.340 for the 31-tap). Near base-Nyquist the 31-tap only
//! achieved ~6-13 dB, so this is a real fidelity upgrade.
//!
//! ## Polyphase upsampling
//! With the input samples sitting at even positions of the (implicit)
//! zero-stuffed stream, the two 2x output phases decompose into:
//!   - phase 0 (even output index): the even-indexed FIR taps (symmetric
//!     interpolating sub-filter, peak ~0.625 at the center);
//!   - phase 1 (odd output index): the odd-indexed FIR taps, which for a
//!     half-band design reduce to a pure delay (center odd tap ~= 1.0).
//!
//! ## Polyphase downsampling
//! The decimator is the same FIR at half gain (DC gain 1) applied to the 2x
//! stream, keeping one output per input. The interpolator already band-limited
//! the signal, so the cascade upsample -> downsample is a delayed identity.
//!
//! ## Group delay / latency
//! Each 63-tap pass has group delay (63-1)/2 = 31 at the 2x rate; the two
//! passes (interpolate then decimate) sum to 62 at the 2x rate = 31 base-rate
//! samples. As measured by the `upsample_then_downsample_is_unity_after_latency`
//! test, the cascade group delay centers on a half-integer between 31 and 32
//! base-rate samples (max_err is identical at either); we fold one extra
//! base-rate sample into the decimator history read (the same technique used
//! for the 31-tap version, which centered on 16) so the reported latency lands
//! on the upper integer 32. Hence `latency_samples()` reports 32.
//!
//! All state is fixed-size arrays + a `usize` index (ring buffers); no `Vec`,
//! `Box`, or any heap allocation in `upsample`/`downsample`.

const N: usize = 63;

// Pasted verbatim from `tools/gen_fir_coeffs.py` (10 significant digits). Some
// near-zero half-band taps carry more precision than f32 can represent; that is
// harmless (they round to the same f32) so we keep the exact generator output.
#[allow(clippy::excessive_precision)]
const COEFFS: [f32; N] = [
    -2.7364620685e-05,
    3.9112619370e-19,
    1.4735964956e-04,
    -4.5038590649e-19,
    -4.3184131143e-04,
    -1.3148348088e-18,
    9.9747418015e-04,
    -2.1071060505e-18,
    -2.0040451704e-03,
    1.3404860470e-17,
    3.6601092542e-03,
    -5.8928080617e-18,
    -6.2299825022e-03,
    8.7715525155e-18,
    1.0046578840e-02,
    -1.2297010516e-17,
    -1.5539858360e-02,
    1.6365686609e-17,
    2.3302289347e-02,
    -2.0793244492e-17,
    -3.4242258580e-02,
    2.5324350189e-17,
    4.9963824539e-02,
    -2.9654204738e-17,
    -7.3822772894e-02,
    3.3459566210e-17,
    1.1454226430e-01,
    -3.6435230365e-17,
    -2.0430706388e-01,
    3.8330725554e-17,
    6.3394618122e-01,
    9.9999821198e-01,
    6.3394618122e-01,
    3.8330725554e-17,
    -2.0430706388e-01,
    -3.6435230365e-17,
    1.1454226430e-01,
    3.3459566210e-17,
    -7.3822772894e-02,
    -2.9654204738e-17,
    4.9963824539e-02,
    2.5324350189e-17,
    -3.4242258580e-02,
    -2.0793244492e-17,
    2.3302289347e-02,
    1.6365686609e-17,
    -1.5539858360e-02,
    -1.2297010516e-17,
    1.0046578840e-02,
    8.7715525155e-18,
    -6.2299825022e-03,
    -5.8928080617e-18,
    3.6601092542e-03,
    1.3404860470e-17,
    -2.0040451704e-03,
    -2.1071060505e-18,
    9.9747418015e-04,
    -1.3148348088e-18,
    -4.3184131143e-04,
    -4.5038590649e-19,
    1.4735964956e-04,
    3.9112619370e-19,
    -2.7364620685e-05,
];

/// Number of input samples in the interpolator delay line. Covers the
/// even-indexed taps (indices 0,2,..,62 -> 32 taps) and odd-indexed taps
/// (1,3,..,61 -> 31 taps); (N+1)/2 = 32 entries is enough for both phases.
const UP_HIST: usize = N.div_ceil(2);

/// Length of the 2x-rate decimator delay line. It must hold the full FIR
/// support (63 taps) plus 2 extra 2x-rate samples (= 1 base-rate sample) so the
/// cascade group delay lands on exactly 32 base-rate samples.
const DOWN_HIST: usize = N + 2;

pub struct Oversample2x {
    /// Ring buffer of the most recent base-rate input samples (newest first
    /// when read via `up_idx`). Used by both upsample phases.
    up_buf: [f32; UP_HIST],
    up_idx: usize,
    /// Ring buffer of the most recent 2x-rate samples fed to `downsample`.
    down_buf: [f32; DOWN_HIST],
    down_idx: usize,
}

impl Oversample2x {
    pub const fn new() -> Self {
        Self {
            up_buf: [0.0; UP_HIST],
            up_idx: 0,
            down_buf: [0.0; DOWN_HIST],
            down_idx: 0,
        }
    }

    /// Upsample one base-rate sample to two 2x-rate samples (phase 0, phase 1).
    pub fn upsample(&mut self, x: f32) -> (f32, f32) {
        // Push newest input into the ring buffer.
        self.up_idx = (self.up_idx + UP_HIST - 1) % UP_HIST;
        self.up_buf[self.up_idx] = x;

        // Polyphase convolution. tap j of a phase reads input (j) samples back.
        let mut phase0 = 0.0f32; // even-indexed FIR taps: COEFFS[2*j]
        let mut phase1 = 0.0f32; // odd-indexed FIR taps:  COEFFS[2*j+1]
        let mut j = 0usize;
        while j < UP_HIST {
            let xj = self.up_buf[(self.up_idx + j) % UP_HIST];
            phase0 += COEFFS[2 * j] * xj;
            if 2 * j + 1 < N {
                phase1 += COEFFS[2 * j + 1] * xj;
            }
            j += 1;
        }
        (phase0, phase1)
    }

    /// Downsample two 2x-rate samples back to one base-rate sample.
    pub fn downsample(&mut self, y0: f32, y1: f32) -> f32 {
        // Push the two 2x-rate samples (phase 0 then phase 1) into the ring.
        self.down_idx = (self.down_idx + DOWN_HIST - 1) % DOWN_HIST;
        self.down_buf[self.down_idx] = y1;
        self.down_idx = (self.down_idx + DOWN_HIST - 1) % DOWN_HIST;
        self.down_buf[self.down_idx] = y0;

        // Half-band decimation at DC gain 1 (COEFFS has DC gain 2). The read is
        // offset by 2 extra 2x-rate samples (= 1 base-rate sample) so the
        // cascade group delay is exactly 32 base-rate samples.
        let mut acc = 0.0f32;
        let mut k = 0usize;
        while k < N {
            let v = self.down_buf[(self.down_idx + 2 + k) % DOWN_HIST];
            acc += COEFFS[k] * v;
            k += 1;
        }
        acc * 0.5
    }

    pub fn reset(&mut self) {
        self.up_buf = [0.0; UP_HIST];
        self.up_idx = 0;
        self.down_buf = [0.0; DOWN_HIST];
        self.down_idx = 0;
    }
}

impl Default for Oversample2x {
    fn default() -> Self {
        Self::new()
    }
}
